CREATE POLICY "memories_read_all" ON storage.objects FOR SELECT USING (bucket_id IN ('memories','avatars'));
CREATE POLICY "memories_insert_own_folder" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id IN ('memories','avatars') AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "memories_update_own_folder" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id IN ('memories','avatars') AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id IN ('memories','avatars') AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "memories_delete_own_folder" ON storage.objects FOR DELETE TO authenticated USING (bucket_id IN ('memories','avatars') AND (storage.foldername(name))[1] = auth.uid()::text);